* ,
::before,
::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
}

.container {
  display: flex;
  justify-content: center;  /* 主軸對齊 */
  align-items: center;      /* 交叉軸對齊 */
  gap: 16px;                /* 子元素間距 */
  flex-wrap: wrap;          /* 換行 */
}

.center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}
/* 原理：移動「自身的一半」 */

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.element {
  animation: slideIn 0.5s ease;
}

/* 斷點 sm (576px)、md (768px)、lg (992px)、xl (1200px)、xxl (1400px) 五個預設斷點 */
@media (max-width: 768px) {
  .container {
    flex-direction: column;
  }
}

@media (min-width: 1380px) {
  .container {
    max-width: 1280px;
  }
}

.col {
  width: calc(100% - 20px);
  height: calc(100vh - 60px);
}
/* ⚠ 過度使用會增加計算負擔 */

