nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  /* nav 內容對齊：容器寬高固定 → 扣除 padding → 對齊內容 */
}

.go-top {
  width: 80px;
  height: 80px;
  text-align: center;
  border-radius: 50%;
  position: fixed;
  bottom: 50px;
  right: 10%;
  background-image: url(./img/go-top.png);
  background-size: cover;
  transform: translateX(-40px);
  transition: 0.5s;
}
.go-top:hover {
  background-image: url(./img/go-top-hover.png);
  background-color: #5e9fa4;
}

